void stage(VuState &vu) {
    float (*vf)[4] = vu.vf;
    int32_t *vi = vu.vi;

    auto set_mac = [&](float res[4], int written_mask) {
        for (int c = 0; c < 4; ++c) {
            if (!(written_mask & (1 << (3 - c)))) continue;
            float r = fix_float(res[c]);
            if (r == 0.0f) vu.mac |= (1 << (3 - c));
            if (r < 0.0f) vu.mac |= (0x10 << (3 - c));
        }
    };

    // 0x0640: NOP / LQI.xyzw vf11, (vi3++)
    {
        std::memcpy(vf[11], vu.mem + 16 * (vi[3] & 0x3FF), 16);
        vi[3] = vi16(vi[3] + 1);
    }

    // 0x0648: NOP / LQI.xyzw vf12, (vi3++)
    {
        std::memcpy(vf[12], vu.mem + 16 * (vi[3] & 0x3FF), 16);
        vi[3] = vi16(vi[3] + 1);
    }

    // 0x0650: NOP / LQI.xyzw vf13, (vi3++)
    {
        std::memcpy(vf[13], vu.mem + 16 * (vi[3] & 0x3FF), 16);
        vi[3] = vi16(vi[3] + 1);
    }

    // 0x0658: NOP / LQI.xyzw vf14, (vi3++)
    {
        std::memcpy(vf[14], vu.mem + 16 * (vi[3] & 0x3FF), 16);
        vi[3] = vi16(vi[3] + 1);
    }

    // 0x0660: NOP / LQ.xyzw vf28, 0(vi3)
    {
        std::memcpy(vf[28], vu.mem + 16 * (vi[3] & 0x3FF), 16);
    }

    // 0x0668: NOP / LQI.xyzw vf15, (vi4++)
    {
        std::memcpy(vf[15], vu.mem + 16 * (vi[4] & 0x3FF), 16);
        vi[4] = vi16(vi[4] + 1);
    }

    // 0x0670: NOP / LQI.xyzw vf16, (vi4++)
    {
        std::memcpy(vf[16], vu.mem + 16 * (vi[4] & 0x3FF), 16);
        vi[4] = vi16(vi[4] + 1);
    }

    // 0x0678: NOP / LQI.xyzw vf17, (vi4++)
    {
        std::memcpy(vf[17], vu.mem + 16 * (vi[4] & 0x3FF), 16);
        vi[4] = vi16(vi[4] + 1);
    }

    // 0x0680: NOP / LQI.xyzw vf18, (vi4++)
    {
        std::memcpy(vf[18], vu.mem + 16 * (vi[4] & 0x3FF), 16);
        vi[4] = vi16(vi[4] + 1);
    }

    // 0x0688: SUB.xyzw vf19, vf26, vf11
    for (int c = 0; c < 4; ++c) vf[19][c] = fix_float(fix_float(vf[26][c]) - fix_float(vf[11][c]));
    set_mac(vf[19], 0xF);
    // ISUBIU vi10, vi10, 1
    vi[10] = vi16(vi[10] - 1);

    // 0x0690: SUB.xyzw vf20, vf26, vf12
    for (int c = 0; c < 4; ++c) vf[20][c] = fix_float(fix_float(vf[26][c]) - fix_float(vf[12][c]));
    set_mac(vf[20], 0xF);
    // NOP

    // 0x0698: SUB.xyzw vf21, vf26, vf13
    for (int c = 0; c < 4; ++c) vf[21][c] = fix_float(fix_float(vf[26][c]) - fix_float(vf[13][c]));
    set_mac(vf[21], 0xF);
    // NOP

    // 0x06a0: SUB.xyzw vf22, vf26, vf14
    for (int c = 0; c < 4; ++c) vf[22][c] = fix_float(fix_float(vf[26][c]) - fix_float(vf[14][c]));
    set_mac(vf[22], 0xF);
    // NOP

    // 0x06a8: MUL.xyzw vf19, vf19, vf15
    for (int c = 0; c < 4; ++c) vf[19][c] = fix_float(fix_float(vf[19][c]) * fix_float(vf[15][c]));
    set_mac(vf[19], 0xF);
    // NOP

    // 0x06b0: MUL.xyzw vf20, vf20, vf16
    for (int c = 0; c < 4; ++c) vf[20][c] = fix_float(fix_float(vf[20][c]) * fix_float(vf[16][c]));
    set_mac(vf[20], 0xF);
    // NOP

    // 0x06b8: MUL.xyzw vf21, vf21, vf17
    for (int c = 0; c < 4; ++c) vf[21][c] = fix_float(fix_float(vf[21][c]) * fix_float(vf[17][c]));
    set_mac(vf[21], 0xF);
    // NOP

    // 0x06c0: MUL.xyzw vf22, vf22, vf18
    for (int c = 0; c < 4; ++c) vf[22][c] = fix_float(fix_float(vf[22][c]) * fix_float(vf[18][c]));
    set_mac(vf[22], 0xF);
    // NOP

    // 0x06c8: ADDy.x vf19, vf19, vf19y
    vf[19][0] = fix_float(fix_float(vf[19][0]) + fix_float(vf[19][1]));
    set_mac(vf[19], 0x8);
    // NOP

    // 0x06d0: ADDy.x vf20, vf20, vf20y
    vf[20][0] = fix_float(fix_float(vf[20][0]) + fix_float(vf[20][1]));
    set_mac(vf[20], 0x8);
    // NOP

    // 0x06d8: ADDy.x vf21, vf21, vf21y
    vf[21][0] = fix_float(fix_float(vf[21][0]) + fix_float(vf[21][1]));
    set_mac(vf[21], 0x8);
    // NOP

    // 0x06e0: ADDy.x vf22, vf22, vf22y
    vf[22][0] = fix_float(fix_float(vf[22][0]) + fix_float(vf[22][1]));
    set_mac(vf[22], 0x8);
    // NOP

    // 0x06e8: ADDz.x vf19, vf19, vf19z
    vf[19][0] = fix_float(fix_float(vf[19][0]) + fix_float(vf[19][2]));
    set_mac(vf[19], 0x8);
    // NOP

    // 0x06f0: ADDz.x vf20, vf20, vf20z
    vf[20][0] = fix_float(fix_float(vf[20][0]) + fix_float(vf[20][2]));
    set_mac(vf[20], 0x8);
    // NOP

    // 0x06f8: ADDz.x vf21, vf21, vf21z
    vf[21][0] = fix_float(fix_float(vf[21][0]) + fix_float(vf[21][2]));
    set_mac(vf[21], 0x8);
    // NOP

    // 0x0700: ADDz.x vf22, vf22, vf22z
    vf[22][0] = fix_float(fix_float(vf[22][0]) + fix_float(vf[22][2]));
    set_mac(vf[22], 0x8);
    // NOP

    // 0x0708: MULx.xyzw vf15, vf15, vf19x
    {
        float mul_val = fix_float(vf[19][0]);
        for (int c = 0; c < 4; ++c) vf[15][c] = fix_float(fix_float(vf[15][c]) * mul_val);
        set_mac(vf[15], 0xF);
    }
    // NOP

    // 0x0710: MULx.xyzw vf16, vf16, vf20x
    {
        float mul_val = fix_float(vf[20][0]);
        for (int c = 0; c < 4; ++c) vf[16][c] = fix_float(fix_float(vf[16][c]) * mul_val);
        set_mac(vf[16], 0xF);
    }
    // NOP

    // 0x0718: MULx.xyzw vf17, vf17, vf21x
    {
        float mul_val = fix_float(vf[21][0]);
        for (int c = 0; c < 4; ++c) vf[17][c] = fix_float(fix_float(vf[17][c]) * mul_val);
        set_mac(vf[17], 0xF);
    }
    // NOP

    // 0x0720: MULx.xyzw vf18, vf18, vf22x
    {
        float mul_val = fix_float(vf[22][0]);
        for (int c = 0; c < 4; ++c) vf[18][c] = fix_float(fix_float(vf[18][c]) * mul_val);
        set_mac(vf[18], 0xF);
    }
    // NOP

    // 0x0728: ADD.xyzw vf19, vf11, vf15
    for (int c = 0; c < 4; ++c) vf[19][c] = fix_float(fix_float(vf[11][c]) + fix_float(vf[15][c]));
    set_mac(vf[19], 0xF);
    // NOP

    // 0x0730: ADD.xyzw vf20, vf12, vf16
    for (int c = 0; c < 4; ++c) vf[20][c] = fix_float(fix_float(vf[12][c]) + fix_float(vf[16][c]));
    set_mac(vf[20], 0xF);
    // NOP

    // 0x0738: ADD.xyzw vf21, vf13, vf17
    for (int c = 0; c < 4; ++c) vf[21][c] = fix_float(fix_float(vf[13][c]) + fix_float(vf[17][c]));
    set_mac(vf[21], 0xF);
    // NOP

    // 0x0740: ADD.xyzw vf22, vf14, vf18
    for (int c = 0; c < 4; ++c) vf[22][c] = fix_float(fix_float(vf[14][c]) + fix_float(vf[18][c]));
    set_mac(vf[22], 0xF);
    // NOP

    vu.pc = 0x748;
}
