    // 0x920: ADDz.x vf16, vf16, vf16z
    // 0x920: NOP
    {
        float a = normalize_op(vf[16][0]);
        float b = normalize_op(vf[16][2]);
        float r = clamp_result(a + b);
        vf[16][0] = r;
        update_mac_lane(mac, 0, r);
    }

