    // 0x970: FMAND vi8, vi9 [MAC flags of the upper instruction at 0x950]
    {
        for(int i=0; i<4; ++i) {
            float a = normalize_op(vf[12][i]);
            float b = normalize_op(0.0f);
            float r = clamp_result(a + b);
            vf[20][i] = r;
            update_mac_lane(mac, i, r);
        }

        vi[8] = mac_950 & vi[9];
    }

