namespace p9_call4 {

void stage(VuState &vu) {
    // 0x0440: NOP                                BAL vi15, 0xf50
    {
        // BAL vi15, 0xf50
        // vi[T] = (address of the pair after the delay slot) / 8
        // Delay slot is at 0x0448, so the next pair is at 0x0450. 0x0450 / 8 = 138.
        vu.vi[15] = 138;

        // 0x0448: NOP                                SQ.xyzw vf20, 1018(vi0)   [delay slot of the branch above: executes before the jump, also when it is taken]
        // SQ.xyzw vf20, 1018(vi0): Store vf20 (all lanes) to memory at address vi[0] + 1018.
        // Address wraps at 1024 qwords.
        int addr = (vu.vi[0] + 1018) & 0x3FF;
        memcpy(&vu.mem[addr * 16], &vu.vf[20][0], 16);

        // Set the program counter to the branch target and return.
        vu.pc = 0xf50;
    }
    return;
}
}
