static float normalize(float f) {
    uint32_t bits;
    std::memcpy(&bits, &f, sizeof(bits));
    if ((bits & 0x7f800000) == 0) {
        return std::copysignf(0.0f, f);
    }
    if ((bits & 0x7f800000) == 0x7f800000) {
        uint32_t max_bits = 0x7f7fffff | (bits & 0x80000000);
        float res;
        std::memcpy(&res, &max_bits, sizeof(res));
        return res;
    }
    return f;
}

static float clamp_result(float f) {
    if (std::isinf(f)) {
        return std::copysignf(std::numeric_limits<float>::max(), f);
    }
    if (f != 0.0f && std::fabs(f) < std::numeric_limits<float>::min()) {
        return std::copysignf(0.0f, f);
    }
    return f;
}

void stage(VuState &vu) {
    // 1210: MULAw.x ACC, vf29, vf16w
    // Lower: IADDIU vi11, vi0, 5
    {
        float vf29_x = normalize(vu.vf[29][0]);
        float vf16_w = normalize(vu.vf[16][3]);
        float res = vf29_x * vf16_w;
        res = clamp_result(res);
        vu.acc[0] = res;

        vu.mac = 0;
        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;

        vu.vi[11] = (int32_t)(int16_t)(vu.vi[0] + 5);
    }

    // 1218: MSUBAw.x ACC, vf9, vf16w
    // Lower: NOP
    {
        float vf9_x = normalize(vu.vf[9][0]);
        float vf16_w = normalize(vu.vf[16][3]);
        float acc_x = normalize(vu.acc[0]);
        float res = acc_x - vf9_x * vf16_w;
        res = clamp_result(res);
        vu.acc[0] = res;

        vu.mac = 0;
        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;
    }

    // 1220: MADDw.x vf22, vf18, vf0w
    // Lower: NOP
    {
        float vf18_x = normalize(vu.vf[18][0]);
        float acc_x = normalize(vu.acc[0]);
        float res = acc_x + vf18_x * 1.0f;
        res = clamp_result(res);
        vu.vf[22][0] = res;

        vu.mac = 0;
        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;
    }

    // 1228: MULw.x vf17, vf27, vf16w
    // Lower: NOP
    {
        float vf27_x = normalize(vu.vf[27][0]);
        float vf16_w = normalize(vu.vf[16][3]);
        float res = vf27_x * vf16_w;
        res = clamp_result(res);
        vu.vf[17][0] = res;

        vu.mac = 0;
        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;
    }

    // 1230: ADDx.yzw vf23, vf18, vf0x
    // Lower: MOVE.yzw vf22, vf19
    {
        vu.mac = 0;
        for (int l = 1; l <= 3; ++l) {
            float vf18_l = normalize(vu.vf[18][l]);
            float res = vf18_l + 0.0f;
            res = clamp_result(res);
            vu.vf[23][l] = res;

            if (res == 0.0f) {
                if (l == 1) vu.mac |= 4;
                else if (l == 2) vu.mac |= 2;
                else if (l == 3) vu.mac |= 1;
            }
            if (res < 0.0f) {
                if (l == 1) vu.mac |= 0x40;
                else if (l == 2) vu.mac |= 0x20;
                else if (l == 3) vu.mac |= 0x10;
            }
        }
        for (int l = 1; l <= 3; ++l) {
            vu.vf[22][l] = vu.vf[19][l];
        }
    }

    // 1238: ADDx.yzw vf25, vf9, vf0x
    // Lower: MOVE.yzw vf24, vf10
    {
        vu.mac = 0;
        for (int l = 1; l <= 3; ++l) {
            float vf9_l = normalize(vu.vf[9][l]);
            float res = vf9_l + 0.0f;
            res = clamp_result(res);
            vu.vf[25][l] = res;

            if (res == 0.0f) {
                if (l == 1) vu.mac |= 4;
                else if (l == 2) vu.mac |= 2;
                else if (l == 3) vu.mac |= 1;
            }
            if (res < 0.0f) {
                if (l == 1) vu.mac |= 0x40;
                else if (l == 2) vu.mac |= 0x20;
                else if (l == 3) vu.mac |= 0x10;
            }
        }
        for (int l = 1; l <= 3; ++l) {
            vu.vf[24][l] = vu.vf[10][l];
        }
    }

    // 1240: ADDx.x vf24, vf29, vf0x
    // Lower: SQ.xyzw vf21, 1(vi6)
    {
        vu.mac = 0;
        float vf29_x = normalize(vu.vf[29][0]);
        float res = vf29_x + 0.0f;
        res = clamp_result(res);
        vu.vf[24][0] = res;

        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;

        int addr = (vu.vi[6] + 1) & 0x3FF;
        int off = addr * 16;
        for (int l = 0; l < 4; ++l) {
            std::memcpy(&vu.mem[off + l*4], &vu.vf[21][l], 4);
        }
    }

    // 1248: ADDx.x vf25, vf29, vf0x
    // Lower: SQ.xyzw vf18, 0(vi6)
    {
        vu.mac = 0;
        float vf29_x = normalize(vu.vf[29][0]);
        float res = vf29_x + 0.0f;
        res = clamp_result(res);
        vu.vf[25][0] = res;

        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;

        int addr = vu.vi[6] & 0x3FF;
        int off = addr * 16;
        for (int l = 0; l < 4; ++l) {
            std::memcpy(&vu.mem[off + l*4], &vu.vf[18][l], 4);
        }
    }

    // 1250: ADDx.x vf23, vf22, vf0x
    // Lower: SQ.xyzw vf14, 2(vi6)
    {
        vu.mac = 0;
        float vf22_x = normalize(vu.vf[22][0]);
        float res = vf22_x + 0.0f;
        res = clamp_result(res);
        vu.vf[23][0] = res;

        if (res == 0.0f) vu.mac |= 8;
        if (res < 0.0f) vu.mac |= 0x80;

        int addr = (vu.vi[6] + 2) & 0x3FF;
        int off = addr * 16;
        for (int l = 0; l < 4; ++l) {
            std::memcpy(&vu.mem[off + l*4], &vu.vf[14][l], 4);
        }
    }

    vu.pc = 0x1258;
}
